    }

    /// Decodes the wire value, never failing on unrecognized values.
    ///
    /// - Parameter decoder: The decoder positioned at the value.
    /// - Throws: `DecodingError` when the wire value is not a String.
    public init(from decoder: any Decoder) throws {
        self.init(wireValue: try decoder.singleValueContainer().decode(String.self))
    }

    /// Encodes the wire value; `.unknown` re-emits the value it captured.
    ///
    /// - Parameter encoder: The encoder to write the value into.
    /// - Throws: Rethrows any error from the underlying encoder.
    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(wireValue)
    }
}

/// Categories of tools that can be invoked.
///
/// Tool kinds help clients choose appropriate icons and optimize how they
/// display tool execution progress.
///
/// See protocol docs: [Reporting](https://agentclientprotocol.com/protocol/v2/tool-calls#reporting)
public enum ToolKind: Codable, Hashable, Sendable {
    /// Reading files or data.
    case read

    /// Modifying files or content.
    case edit

    /// Removing files or data.
    case delete

    /// Moving or renaming files.
    case move

    /// Searching for information.
    case search

    /// Running commands or code.
    case execute

    /// Internal reasoning or planning.
    case think

    /// Retrieving external data.
    case fetch

    /// Changing the session's mode, a [config option](https://agentclientprotocol.com/protocol/v2/session-config-options) with the `mode` category.
    case switchMode

    /// Other tool types (default).
    case other

    /// An unrecognized wire value, captured verbatim so a newer peer's
    /// value decodes without error and re-encodes unchanged.
    case unknown(String)

    private enum Tag: String {
        case read = "read"
        case edit = "edit"
        case delete = "delete"
        case move = "move"
        case search = "search"
        case execute = "execute"
        case think = "think"
        case fetch = "fetch"
        case switchMode = "switch_mode"
        case other = "other"
    }

    /// The value as it crosses the wire.
    public var wireValue: String {
        switch self {
        case .read: Tag.read.rawValue
        case .edit: Tag.edit.rawValue
        case .delete: Tag.delete.rawValue
        case .move: Tag.move.rawValue
        case .search: Tag.search.rawValue
        case .execute: Tag.execute.rawValue
        case .think: Tag.think.rawValue
        case .fetch: Tag.fetch.rawValue
        case .switchMode: Tag.switchMode.rawValue
        case .other: Tag.other.rawValue
        case .unknown(let value): value
        }
    }

    /// Creates the case matching a wire value, routing unrecognized
    /// values to `.unknown`.
    ///
    /// - Parameter wireValue: The value as it crosses the wire.
    public init(wireValue: String) {
        switch wireValue {
        case Tag.read.rawValue: self = .read
        case Tag.edit.rawValue: self = .edit
        case Tag.delete.rawValue: self = .delete
        case Tag.move.rawValue: self = .move
        case Tag.search.rawValue: self = .search
        case Tag.execute.rawValue: self = .execute
        case Tag.think.rawValue: self = .think
        case Tag.fetch.rawValue: self = .fetch
        case Tag.switchMode.rawValue: self = .switchMode
        case Tag.other.rawValue: self = .other
        default: self = .unknown(wireValue)
        }
    }

    /// Decodes the wire value, never failing on unrecognized values.
    ///
    /// - Parameter decoder: The decoder positioned at the value.
    /// - Throws: `DecodingError` when the wire value is not a String.
    public init(from decoder: any Decoder) throws {
        self.init(wireValue: try decoder.singleValueContainer().decode(String.self))
    }

    /// Encodes the wire value; `.unknown` re-emits the value it captured.
    ///
    /// - Parameter encoder: The encoder to write the value into.
    /// - Throws: Rethrows any error from the underlying encoder.
    public func encode(to encoder: any Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(wireValue)
    }
}
